#define LED_PIN 2  // onboard LED on most ESP32 dev boards

void setup() {
  Serial.begin(115200);
  delay(1000);

  pinMode(LED_PIN, OUTPUT);

  Serial.println();
  Serial.println("=== ESP32 test ===");
  Serial.printf("Chip model: %s, revision %d\n", ESP.getChipModel(), ESP.getChipRevision());
  Serial.printf("CPU: %d MHz, cores: %d\n", ESP.getCpuFreqMHz(), ESP.getChipCores());
  Serial.printf("Flash size: %u KB\n", ESP.getFlashChipSize() / 1024);
  Serial.printf("Flash speed: %u MHz\n", ESP.getFlashChipSpeed() / 1000000);
  Serial.printf("Free heap: %u bytes\n", ESP.getFreeHeap());
}

void loop() {
  digitalWrite(LED_PIN, HIGH);
  Serial.println("LED ON");
  delay(500);

  digitalWrite(LED_PIN, LOW);
  Serial.println("LED OFF");
  delay(500);
}
